{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Pentazocine, the highest-transfer analogue, has a mean absolute oral bioavailability of 18% in healthy subjects, below the 20% threshold; its F rises to 70% in cirrhosis, confirming extensive first-pass hepatic extraction that is mechanistically relevant to the unmodified steroid diketone query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Ethinylestradiol shows ~43% oral bioavailability, but its 17α-ethynyl group and phenolic A-ring confer metabolic protection absent in the query, so this high value does not transfer to the unmodified diketone steroid.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C39"],
      "claim": "Ursodeoxycholic acid shows 50% systemic availability, but as a bile acid it benefits from active enterohepatic/transporter-mediated absorption, not representative of the neutral steroid query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C05"],
      "claim": "Digitoxin shows >90% oral bioavailability, but as a cardiac glycoside with sugar moieties and a lactone, its absorption and metabolic stability differ substantially from the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Prediction is low: the strongest single anchor (pentazocine, F=18% in healthy subjects) and the query's unmodified steroid scaffold with 3-keto-4-ene and 17-ketone, prone to first-pass reduction/conjugation, support F<20%. The many high-F analogues are structurally modified steroids with metabolic protection or transporter-mediated absorption, making them less mechanistically transferable.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query steroid itself.",
    "No analogue with the same unmodified 3-keto-4-ene-17-one steroid scaffold.",
    "High-F analogues contain protective groups (ethynyl, sugars) or are transporter substrates, limiting direct extrapolation."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

